  const db = getDb();
  const pending = db
    .select({ delivery: webhookDeliveries })
    .from(webhookDeliveries)
    .innerJoin(organizations, eq(organizations.id, webhookDeliveries.orgId))
    .where(and(eq(webhookDeliveries.status, "pending"), isNull(organizations.archivedAt)))
    .orderBy(asc(webhookDeliveries.createdAt))
    .limit(Math.max(1, limit))
    .all();

  return pending.map((row) =>
    db
      .update(webhookDeliveries)
      .set({
        attempts: row.attempts + 1,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(eq(webhookDeliveries.id, row.id))
      .returning()
      .get(),
  );
}

